ngth(name) >= 1 AND length(name) <= 120)","inheritance_count":0,"kind":"c","local":true,"no_inherit":false,"validated":true}},{"key":"public.return_credit206_series.return_credit206_series_name_not_null","kind":"constraint","value":{"deferrable":false,"deferred":false,"definition":"NOT NULL name","inheritance_count":0,"kind":"n","local":true,"no_inherit":false,"validated":true}},{"key":"public.return_credit206_series.return_credit206_series_pkey","kind":"constraint","value":{"deferrable":false,"deferred":false,"definition":"PRIMARY KEY (id)","inheritance_count":0,"kind":"p","local":true,"no_inherit":true,"validated":true}},{"key":"public.return_credit206_series.return_credit206_series_prefix_check","kind":"constraint","value":{"deferrable":false,"deferred":false,"definition":"CHECK (prefix ~ '^[A-Z0-9][A-Z0-9-]{0,23}$'::text)","inheritance_count":0,"kind":"c","local":true,"no_inherit":false,"validated":true}},{"key":"public.return_credit206_series.return_credit206_series_prefix_not_null","kind":"constraint","value":{"deferrable":false,"deferred":false,"definition":"NOT NULL prefix","inheritance_count":0,"kind":"n","local":true,"no_inherit":false,"validated":true}},{"key":"public.return_credit206_series.return_credit206_series_request_hash_check","kind":"constraint","value":{"deferrable":false,"deferred":false,"definition":"CHECK (request_hash ~ '^[a-f0-9]{64}$'::text)","inheritance_count":0,"kind":"c","local":true,"no_inherit":false,"validated":true}},{"key":"public.return_credit206_series.return_credit206_series_request_hash_not_null","kind":"constraint","value":{"deferrable":false,"deferred":false,"definition":"NOT NULL request_hash","inheritance_count":0,"kind":"n","local":true,"no_inherit":false,"validated":true}},{"key":"public.return_credit206_series.return_credit206_series_request_not_null","kind":"constraint","value":{"deferrable":false,"deferred":false,"definition":"NOT NULL request","inheritance_count":0,"kind":"n","local":true,"no_inherit":false,"validate