SELECT 'relation',n.nspname||'.'||c.relname,jsonb_build_object('owner',pg_catalog.pg_get_userbyid(c.relowner),'kind',c.relkind,'persistence',c.relpersistence,'access_method',(SELECT amname FROM pg_catalog.pg_am WHERE oid=c.relam),'row_security',c.relrowsecurity,'force_row_security',c.relforcerowsecurity,'replica_identity',c.relreplident,'partition',c.relispartition,'partition_bound',pg_catalog.pg_get_expr(c.relpartbound,c.oid),'partition_key',CASE WHEN c.relkind='p' THEN pg_catalog.pg_get_partkeydef(c.oid) ELSE NULL END,'options',c.reloptions,'tablespace',(SELECT spcname FROM pg_catalog.pg_tablespace WHERE oid=c.reltablespace),'acl_null',c.relacl IS NULL,'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_catalog.pg_get_userbyid(a.grantor),'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY a.grantor::regrole::text,CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END,a.privilege_type,a.is_grantable),'[]'::jsonb) FROM pg_catalog.aclexplode(CASE WHEN pg_catalog.cardinality(coalesce(c.relacl,pg_catalog.acldefault(CASE WHEN c.relkind='S' THEN 's'::"char" ELSE 'r'::"char" END,c.relowner)))=0 THEN NULL::aclitem[] ELSE coalesce(c.relacl,pg_catalog.acldefault(CASE WHEN c.relkind='S' THEN 's'::"char" ELSE 'r'::"char" END,c.relowner)) END) a),'view',CASE WHEN c.relkind IN('v','m') THEN pg_catalog.pg_get_viewdef(c.oid,false) ELSE NULL END) FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE c.oid IN(SELECT oid FROM rels)
