 UNION ALL SELECT 'index',n.nspname||'.'||c.relname,jsonb_build_object('table',i.indrelid::regclass::text,'unique',i.indisunique,'primary',i.indisprimary,'exclusion',i.indisexclusion,'immediate',i.indimmediate,'clustered',i.indisclustered,'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive,'replica_identity',i.indisreplident,'nulls_not_distinct',i.indnullsnotdistinct,'definition',pg_catalog.pg_get_indexdef(i.indexrelid,0,false)) FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class c ON c.oid=i.indexrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE i.indrelid IN(SELECT oid FROM rels)
 UNION ALL SELECT 'policy',n.nspname||'.'||c.relname||'.'||p.polname,jsonb_build_object('command',p.polcmd,'permissive',p.polpermissive,'roles',(SELECT jsonb_agg(CASE WHEN x=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(x)::text END ORDER BY CASE WHEN x=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(x)::text END) FROM unnest(p.polroles) x),'using',pg_catalog.pg_get_expr(p.polqual,p.polrelid),'check',pg_catalog.pg_get_expr(p.polwithcheck,p.polrelid)) FROM pg_catalog.pg_policy p JOIN pg_catalog.pg_class c ON c.oid=p.polrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE p.polrelid IN(SELECT oid FROM rels)
 UNION ALL SELECT 'trigger',n.nspname||'.'||c.relname||'.'||CASE WHEN t.tgisinternal THEN 'internal:'||coalesce(k.conname,'')||':'||t.tgfoid::regprocedure::text||':'||t.tgtype::text||':'||coalesce((SELECT string_agg(a.attname,',' ORDER BY u.ord) FROM unnest(t.tgattr::smallint[]) WITH ORDINALITY u(num,ord) JOIN pg_catalog.pg_attribute a ON(a.attrelid,a.attnum)=(t.tgrelid,u.num)),'') ELSE t.tgname::text END,jsonb_build_object('internal',t.tgisinternal,'name',CASE WHEN t.tgisinternal THEN NULL ELSE t.tgname END,'enabled',t.tgenabled,'type',t.tgtype,'function',t.tgfoid::regprocedure::text,'attributes',(SELECT coalesce(jsonb_agg(a.attname ORDER BY u.ord),'[]'::jsonb) FROM unnest(t.tgattr::smallint[]) WITH ORDINALITY u(num,ord) JOIN pg_catalog.pg_attribute a ON(a.attrelid,a.attnum)=(t.tgrelid,u.num)),'arguments',encode(t.tgargs,'hex'),'constraint',k.conname,'constraint_relation',CASE WHEN t.tgconstrrelid=0 THEN NULL ELSE t.tgconstrrelid::regclass::text END,'deferrable',t.tgdeferrable,'deferred',t.tginitdeferred,'has_when',t.tgqual IS NOT NULL,'old_table',t.tgoldtable,'new_table',t.tgnewtable,'definition',CASE WHEN t.tgisinternal THEN NULL ELSE pg_catalog.pg_get_triggerdef(t.oid,false) END) FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_class c ON c.oid=t.tgrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_catalog.pg_constraint k ON k.oid=t.tgconstraint WHERE t.tgrelid IN(SELECT oid FROM rels) OR t.tgconstraint IN(SELECT oid FROM pg_catalog.pg_constraint WHERE conrelid IN(SELECT oid FROM rels))
 UNION ALL SELECT 'function',n.nspname||'.'||p.proname||'('||pg_catalog.pg_get_function_identity_arguments(p.oid)||')',jsonb_build_object('owner',pg_catalog.pg_get_userbyid(p.proowner),'language',l.lanname,'kind',p.prokind,'cost',p.procost,'rows',p.prorows,'security_definer',p.prosecdef,'leakproof',p.proleakproof,'strict',p.proisstrict,'returns_set',p.proretset,'volatility',p.provolatile,'parallel',p.proparallel,'support',CASE WHEN p.prosupport=0 THEN NULL ELSE p.prosupport::regprocedure::text END,'variadic',CASE WHEN p.provariadic=0 THEN NULL ELSE pg_catalog.format_type(p.provariadic,NULL) END,'argument_names',p.proargnames,'argument_modes',p.proargmodes,'arguments',pg_catalog.pg_get_function_arguments(p.oid),'result',pg_catalog.pg_get_function_result(p.oid),'defaults',pg_catalog.pg_get_expr(p.proargdefaults,0),'source',p.prosrc,'binary',p.probin,'config',p.proconfig,'definition',pg_catalog.pg_get_functiondef(p.oid),'acl_null',p.proacl IS NULL,'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_catalog.pg_get_userbyid(a.grantor),'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY a.grantor::regrole::text,CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END,a.privilege_type,a.is_grantable),'[]'::jsonb) FROM pg_catalog.aclexplode(CASE WHEN pg_catalog.cardinality(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner)))=0 THEN NULL::aclitem[] ELSE coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner)) END) a)) FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace JOIN pg_catalog.pg_language l ON l.oid=p.prolang WHERE n.nspname='public' AND starts_with(p.proname,'return_credit208_')
 UNION ALL SELECT 'type',n.nspname||'.'||t.typname,jsonb_build_object('owner',pg_catalog.pg_get_userbyid(t.typowner),'kind',t.typtype,'category',t.typcategory,'defined',t.typisdefined,'not_null',t.typnotnull,'base',CASE WHEN t.typbasetype=0 THEN NULL ELSE pg_catalog.format_type(t.typbasetype,t.typtypmod) END,'element',CASE WHEN t.typelem=0 THEN NULL ELSE pg_catalog.format_type(t.typelem,NULL) END,'default',t.typdefault,'default_expression',pg_catalog.pg_get_expr(t.typdefaultbin,0),'length',t.typlen,'by_value',t.typbyval,'preferred',t.typispreferred,'delimiter',t.typdelim,'relation',CASE WHEN t.typrelid=0 THEN NULL ELSE t.typrelid::regclass::text END,'subscript',CASE WHEN t.typsubscript=0 THEN NULL ELSE t.typsubscript::regprocedure::text END,'array',CASE WHEN t.typarray=0 THEN NULL ELSE pg_catalog.format_type(t.typarray,NULL) END,'input',t.typinput::regprocedure::text,'output',t.typoutput::regprocedure::text,'receive',CASE WHEN t.typreceive=0 THEN NULL ELSE t.typreceive::regprocedure::text END,'send',CASE WHEN t.typsend=0 THEN NULL ELSE t.typsend::regprocedure::text END,'modifier_input',CASE WHEN t.typmodin=0 THEN NULL ELSE t.typmodin::regprocedure::text END,'modifier_output',CASE WHEN t.typmodout=0 THEN NULL ELSE t.typmodout::regprocedure::text END,'analyze',CASE WHEN t.typanalyze=0 THEN NULL ELSE t.typanalyze::regprocedure::text END,'alignment',t.typalign,'storage',t.typstorage,'modifier',t.typtypmod,'dimensions',t.typndims,'collation',CASE WHEN t.typcollation=0 THEN NULL ELSE t.typcollation::regcollation::text END,'enum_labels',(SELECT coalesce(jsonb_agg(e.enumlabel ORDER BY e.enumsortorder),'[]'::jsonb) FROM pg_catalog.pg_enum e WHERE e.enumtypid=t.oid),'acl_null',t.typacl IS NULL,'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_catalog.pg_get_userbyid(a.grantor),'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY a.grantor::regrole::text,CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END,a.privilege_type,a.is_grantable),'[]'::jsonb) FROM pg_catalog.aclexplode(CASE WHEN pg_catalog.cardinality(coalesce(t.typacl,pg_catalog.acldefault('T',t.typowner)))=0 THEN NULL::aclitem[] ELSE coalesce(t.typacl,pg_catalog.acldefault('T',t.typowner)) END) a)) FROM pg_catalog.pg_type t JOIN pg_catalog.pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname='public' AND(starts_with(t.typname,'return_credit208_') OR starts_with(t.typname,'_return_credit208_'))
) SELECT jsonb_build_object('kind',kind,'key',key,'value',value) record FROM entries
) namespace208$fingerprint208$;
-- Close inherited default grants on these NEW objects only; no global role,
-- default privilege, old manifest or existing function ACL is modified.
DO $acl208$ DECLARE r record;BEGIN
 FOR r IN SELECT DISTINCT a.grantee FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid='public.return_credit208_manifest'::regclass AND a.grantee<>c.relowner LOOP
  EXECUTE format('REVOKE ALL ON TABLE public.return_credit208_manifest FROM %s',CASE WHEN r.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(r.grantee)) END);
 END LOOP;
 FOR r IN SELECT DISTINCT a.grantee FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid='public.return_credit208_fingerprint()'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION public.return_credit208_fingerprint() FROM %s',CASE WHEN r.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(r.grantee)) END);
 END LOOP;
END $acl208$;
CREATE OR REPLACE FUNCTION public.return_credit206_guards() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $guard208$DECLARE c record;s record;BEGIN
 IF to_regclass('public.return_credit208_manifest') IS NULL OR to_regprocedure('public.return_credit208_fingerprint()') IS NULL THEN RETURN false;END IF;
 IF(SELECT count(*) FROM public.return_credit208_manifest)<>1 OR(SELECT count(*) FROM pg_class WHERE relnamespace='public'::regnamespace AND starts_with(relname,'return_credit208_') AND relkind IN('r','p'))<>1 OR(SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace AND starts_with(proname,'return_credit208_'))<>1 THEN RETURN false;END IF;
 IF current_setting('session_replication_role')<>'origin' OR(SELECT count(*) FROM return_credit206_manifest)<>1 OR(SELECT count(*) FROM pg_class WHERE relnamespace='public'::regnamespace AND relname LIKE 'return\_credit206\_%' ESCAPE '\' AND relkind IN('r','p') AND relrowsecurity AND relforcerowsecurity)<>8 THEN RETURN false;END IF;
 IF(SELECT count(*) FROM pg_class WHERE relnamespace='public'::regnamespace AND starts_with(relname,'return_credit208_'))<>2 OR(SELECT count(*) FROM pg_type WHERE typnamespace='public'::regnamespace AND(starts_with(typname,'return_credit208_') OR starts_with(typname,'_return_credit208_')))<>2 OR EXISTS(SELECT FROM pg_trigger WHERE starts_with(tgname,'return_credit208_') AND tgrelid<>'public.return_credit208_manifest'::regclass) OR EXISTS(SELECT FROM pg_constraint WHERE connamespace='public'::regnamespace AND starts_with(conname,'return_credit208_') AND conrelid<>'public.return_credit208_manifest'::regclass) THEN RETURN false;END IF;
 SELECT * INTO c FROM return_credit206_manifest WHERE id;
 SELECT * INTO s FROM public.return_credit208_manifest WHERE id;
 RETURN coalesce(c.profile='157+139+148+169+188-to207-consumer-credit/v2' AND s.profile='207-to208-consumer-credit-deduplicated/v1' AND s.original207=to_jsonb(c)
 AND s.successor207_fingerprint=public.return_credit206_fingerprint() AND s.fingerprint=public.return_credit208_fingerprint()
 AND c.original157=(SELECT to_jsonb(m) FROM local_invoice_manifest m WHERE id) AND c.original160=(SELECT to_jsonb(m) FROM b2b_credit_upgrade m WHERE id)
 AND public.local_consumer_credit_guards() AND public.ordinary188_structure_valid(),false);
END$guard208$;
CREATE OR REPLACE FUNCTION public.return_credit206_require(uid uuid,kid uuid,writing boolean,pin boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $require208$BEGIN
 IF NOT public.return_credit206_installed() OR NOT public.return_credit206_guards() THEN RAISE EXCEPTION 'Niepełny profil207' USING ERRCODE='55000';END IF;
 PERFORM public.local_invoice_require(uid,kid,writing,pin);
END$require208$;
INSERT INTO public.return_credit208_manifest(id,profile,original207,successor207_fingerprint,fingerprint)
 SELECT true,'207-to208-consumer-credit-deduplicated/v1',to_jsonb(m),public.return_credit206_fingerprint(),public.return_credit208_fingerprint() FROM public.return_credit206_manifest m WHERE id;
DO $close208$ BEGIN
 IF public.return_credit206_guards() IS DISTINCT FROM true OR public.local_consumer_credit_guards() IS DISTINCT FROM true OR public.ordinary188_structure_valid() IS DISTINCT FROM true THEN RAISE EXCEPTION '208 full successor refused' USING ERRCODE='55000';END IF;
END $close208$;
